// routes/products.js
const express = require('express');
const fs = require('fs');
const path = require('path');
const csv = require('csv-parser');
const { getDb } = require('../db');

const router = express.Router();
const CATALOG_DIR = path.join(__dirname, '..', 'data', 'catalog');

function parseCsv(file) {
  return new Promise((resolve, reject) => {
    const rows = [];
    fs.createReadStream(file)
      .pipe(csv())
      .on('data', (row) => rows.push(row))
      .on('end', () => resolve(rows))
      .on('error', reject);
  });
}

async function readCatalog() {
  const files = (await fs.promises.readdir(CATALOG_DIR)).filter((f) => f.endsWith('.csv'));
  const parsed = await Promise.all(files.map((f) => parseCsv(path.join(CATALOG_DIR, f))));
  return parsed.flat();
}

const clean = (row) => ({ ...row, price: Number(row.price) });

// fixed paths first ...
router.get('/catalog', async (req, res, next) => {
  try { res.json(await readCatalog()); } catch (e) { next(e); }
});

router.post('/bulk-upload', async (req, res, next) => {
  try {
    const rows = req.file ? await parseCsv(req.file.path) : await readCatalog();
    const docs = rows.filter((r) => Object.values(r).some((v) => String(v).trim())).map(clean);
    if (!docs.length) return res.status(400).json({ message: 'No rows to import' });
    const result = await getDb().collection('products').insertMany(docs, { ordered: false });
    res.status(201).json({ inserted: result.insertedCount });
  } catch (e) { next(e); }
});

router.get('/search', async (req, res, next) => {
  try {
    const q = String(req.query.q || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    res.json(await getDb().collection('products').find({ name: { $regex: q, $options: 'i' } }).toArray());
  } catch (e) { next(e); }
});

// ... parameterised route last
router.get('/:productId', async (req, res, next) => {
  try {
    const { ObjectId } = require('mongodb');
    if (!ObjectId.isValid(req.params.productId)) return res.status(400).json({ message: 'Invalid id' });
    const doc = await getDb().collection('products').findOne({ _id: new ObjectId(req.params.productId) });
    if (!doc) return res.status(404).json({ message: 'Product not found' });
    res.json(doc);
  } catch (e) { next(e); }
});

module.exports = router;
